const CATS=['Shirts','Knitwear','Trousers','Outerwear','Accessories','Footwear'];
const money=n=>'₹'+Number(n||0).toLocaleString('en-IN');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=document.querySelector('#app');
const store={products:[],settings:{shippingFee:99,freeShippingThreshold:3000,announcement:'TIMELESS ESSENTIALS. CONSIDERED STYLE.'},me:{authenticated:false},cart:JSON.parse(localStorage.getItem('rr-cart')||'[]'),wish:new Set(JSON.parse(localStorage.getItem('rr-wish')||'[]')),orders:[],addresses:[],query:'',chat:false,messages:[{who:'bot',text:'Welcome. I’m the Regent Concierge. How may I help you dress or shop today?'}],searchOpen:false,menuOpen:false};
let cartSync=Promise.resolve();
const persist=()=>{localStorage.setItem('rr-cart',JSON.stringify(store.cart));if(store.me.authenticated){const body=JSON.stringify({items:store.cart});cartSync=cartSync.then(()=>api('/api/cart',{method:'PUT',body})).catch(error=>console.warn('Cart sync:',error.message))}};
const api=async(path,options={})=>{const r=await fetch(path,{...options,headers:{'content-type':'application/json',...(options.headers||{})}});let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(d.error||'Something went wrong. Please try again.');return d};
const href=(path)=>'#/'+path.replace(/^\//,'');
const qtyCart=()=>store.cart.reduce((n,x)=>n+x.quantity,0);
const lineProduct=id=>store.products.find(p=>p.id===id);
const stockFor=(p,c,s)=>Number(p?.stock?.[c+'|'+s]||0);
const cartMath=()=>{const subtotal=store.cart.reduce((n,x)=>n+(lineProduct(x.productId)?.price||0)*x.quantity,0);const shipping=subtotal===0||subtotal>=store.settings.freeShippingThreshold?0:store.settings.shippingFee;return{subtotal,shipping,total:subtotal+shipping}};
const saveWish=async(id)=>{const active=!store.wish.has(id);active?store.wish.add(id):store.wish.delete(id);localStorage.setItem('rr-wish',JSON.stringify([...store.wish]));if(store.me.authenticated){try{await api('/api/wishlist',{method:'PUT',body:JSON.stringify({productId:id,active})})}catch(e){console.warn(e.message)}}render()};
const addCart=(p,c=p.colours[0]?.name,s=p.sizes[0],q=1)=>{if(stockFor(p,c,s)<q){alert('This variant is currently unavailable.');return}const line=store.cart.find(x=>x.productId===p.id&&x.colour===c&&x.size===s);if(line){if(stockFor(p,c,s)<line.quantity+q){alert('There is not enough stock for that quantity.');return}line.quantity+=q}else store.cart.push({productId:p.id,colour:c,size:s,quantity:q});persist();render()};
const swatches=p=>'<div class="swatches">'+p.colours.map(c=>'<span class="swatch" title="'+esc(c.name)+'" style="background:'+esc(c.hex)+'"></span>').join('')+'</div>';
const card=p=>{const first=p.colours.map(c=>({c,s:p.sizes.find(s=>stockFor(p,c.name,s)>0)})).find(x=>x.s);const quickSize=first?.s||p.sizes[0];const quickDisabled=!first;return '<article class="product-card"><a class="product-image" href="'+href('product/'+p.id)+'"><img loading="lazy" src="'+esc(p.image)+'" alt="'+esc(p.name)+'"><span class="product-tag" '+(!p.is_new?'hidden':'')+'>NEW</span></a><button class="heart '+(store.wish.has(p.id)?'active':'')+'" aria-label="'+(store.wish.has(p.id)?'Remove from':'Add to')+' wishlist" data-wish="'+p.id+'">'+(store.wish.has(p.id)?'♥':'♡')+'</button><div class="product-details"><a class="product-name" href="'+href('product/'+p.id)+'">'+esc(p.name)+'</a><span class="price">'+money(p.price)+'</span></div>'+swatches(p)+'<button class="quick-add" data-quick="'+p.id+'" '+(quickDisabled?'disabled':'')+'>'+(quickDisabled?'Unavailable':'Quick add · '+esc(quickSize))+'</button></article>'};
const header=()=>'<div class="announcement">'+esc(store.settings.announcement)+'</div><header class="header"><button class="icon-btn mobile-menu" data-menu aria-label="Open navigation">☰</button><a class="wordmark" href="#/">ROWAN & REGENT</a><nav class="nav"><a href="'+href('shop')+'">Shop all</a><a href="'+href('new')+'">New arrivals</a><a href="'+href('shop/Shirts')+'">Shirts</a><a href="'+href('shop/Knitwear')+'">Knitwear</a><a href="'+href('shop/Trousers')+'">Trousers</a><a href="'+href('about')+'">Our story</a></nav><div class="nav-tools"><button class="icon-btn" data-search aria-label="Search">⌕</button><a class="icon-btn" href="'+href('account')+'" aria-label="Account">♙</a><a class="icon-btn" href="'+href('wishlist')+'" aria-label="Wishlist">♡</a><a class="icon-btn" href="'+href('cart')+'" aria-label="Shopping bag">♧<span class="count">'+qtyCart()+'</span></a></div></header>'+(store.searchOpen?'<form class="searchbar" id="search-form" style="display:flex;padding:12px 6vw;gap:10px;border-bottom:1px solid var(--line)"><input name="q" aria-label="Search products" placeholder="Search the collection" value="'+esc(store.query)+'" style="flex:1;padding:12px;border:1px solid var(--line);background:transparent"><button class="button small">Search</button></form>':'')+(store.menuOpen?'<nav class="mobile-nav" style="display:grid;position:absolute;z-index:9;background:var(--ivory);left:0;right:0;padding:20px 7vw;box-shadow:0 12px 20px #0001">'+[['Shop all','shop'],['New arrivals','new'],...CATS.map(c=>[c,'shop/'+c]),['Our story','about']].map(([n,u])=>'<a style="padding:10px;border-bottom:1px solid var(--line);font-size:11px;letter-spacing:.1em;text-transform:uppercase" href="'+href(u)+'">'+esc(n)+'</a>').join('')+'</nav>':'');
const footer=()=>'<footer class="footer"><div class="footer-cols"><div class="footer-brand"><a class="wordmark" href="#/">ROWAN & REGENT</a><p>Timeless by nature. Refined by choice.</p><p>Considered essentials, inspired by heritage menswear.</p></div><div><h3>THE COLLECTION</h3>'+[['Shop All','shop'],...CATS.map(c=>[c,'shop/'+c]),['New Arrivals','new']].map(([n,u])=>'<a href="'+href(u)+'">'+n+'</a>').join('')+'</div><div><h3>CLIENT SERVICES</h3>'+[['Contact','contact'],['FAQs','faq'],['Shipping','shipping'],['Returns & refunds','returns'],['Size guide','size-guide']].map(([n,u])=>'<a href="'+href(u)+'">'+n+'</a>').join('')+'</div><div><h3>GET IN TOUCH</h3><a href="mailto:sakshampasrija@gmail.com">sakshampasrija@gmail.com</a><a href="tel:9817322096">9817322096</a>'+(store.settings.instagramUrl?'<a href="'+esc(store.settings.instagramUrl)+'" target="_blank" rel="noopener">Instagram ↗</a>':'')+'<a href="'+href('privacy')+'">Privacy policy</a><a href="'+href('terms')+'">Terms & conditions</a><a href="'+href('admin')+'">Administrator</a></div></div><div class="footer-bottom"><span>© 2026 ROWAN & REGENT</span><span>India · INR</span></div></footer>';
const shell=body=>header()+body+footer()+'<button class="chat-launch" data-chat>REGENT CONCIERGE</button>'+(store.chat?chatPanel():'');
const chatPanel=()=>'<section class="chat-panel" aria-label="Regent Concierge chat"><div class="chat-head"><strong>REGENT CONCIERGE</strong><button data-chat aria-label="Close concierge">×</button></div><div class="chat-messages" id="chat-messages">'+store.messages.map(m=>'<div class="message '+(m.who==='user'?'user':'')+'">'+esc(m.text)+'</div>').join('')+'</div><div class="chat-prompts">'+['Help me build an outfit','Find my size','Track my order','Explain payment','Shipping and returns'].map(t=>'<button data-prompt="'+esc(t)+'">'+esc(t)+'</button>').join('')+'</div><form class="chat-form" id="chat-form"><input name="message" aria-label="Message" placeholder="Ask the concierge…" autocomplete="off"><button>Send</button></form></section>';
const home=()=>'<main><section class="hero"><div class="hero-copy"><span class="eyebrow">ROWAN & REGENT · THE COLLECTION</span><h1>THE ART OF<br>DRESSING WELL.</h1><p>Considered silhouettes. Timeless colours. A wardrobe built beyond seasons.</p><div class="hero-links"><a class="button" href="'+href('shop')+'">Explore the collection</a><a class="text-link" href="'+href('about')+'">Discover our story</a></div></div><div class="hero-image" role="img" aria-label="Model in an ivory shirt and tailored trousers in a European courtyard"></div></section><section class="philosophy"><div><strong>LESS, BUT BETTER.</strong></div><div><strong>STYLE WITHOUT SEASON.</strong></div><div><strong>DETAILS THAT MATTER.</strong></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">A CONSIDERED WARDROBE</span><h2>THE COLLECTION</h2></div><a class="text-link" href="'+href('shop')+'">View all pieces</a></div><div class="product-grid">'+store.products.slice(0,4).map(card).join('')+'</div></section><section class="editorial"><div class="editorial-image" role="img" aria-label="Heritage-inspired knitwear styling"></div><div class="editorial-copy"><span class="eyebrow">THE ESSENTIALS EDIT</span><h2>THE QUIET CONFIDENCE OF A WELL-CHOSEN WARDROBE.</h2><p>From the considered line of a shirt to the ease of a favourite knit, build a wardrobe that feels entirely your own.</p><a class="text-link" href="'+href('shop')+'">Explore the essentials</a></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">FIND YOUR FORM</span><h2>SHOP BY CATEGORY</h2></div></div><div class="category-grid">'+[['Shirts','assets/shirts.png'],['Knitwear','assets/knitwear.png'],['Trousers','assets/trousers.png'],['Outerwear','assets/accessories.png'],['Accessories','assets/accessories.png']].map(([c,img])=>'<a class="category-tile" href="'+href('shop/'+c)+'"><img loading="lazy" src="'+img+'" alt="'+c+' collection"><span>'+c+'</span></a>').join('')+'</div></section><section class="story-band"><span class="eyebrow">A NOTE ON STYLE</span><h2>AN ELEGANT KIND OF EVERYDAY.</h2><p>ROWAN & REGENT is built around the belief that personal style does not need to be loud. We create a considered collection of wardrobe essentials inspired by heritage menswear and the enduring appeal of simplicity.</p><a class="text-link" style="color:white" href="'+href('about')+'">Our point of view</a></section><section class="section"><div class="section-head"><div><span class="eyebrow">A CLOSER LOOK</span><h2>THE COLLECTION</h2></div><a class="text-link" href="'+href('shop')+'">Shop all</a></div><div class="product-grid">'+store.products.slice(4,8).map(card).join('')+'</div></section>'+newsletter()+'</main>';
const newsletter=()=>'<section class="newsletter"><div><h2>LETTERS FROM THE REGENT.</h2><p>Product notes, thoughtful styling and collection announcements.</p></div><form id="newsletter-form"><label class="sr-only" for="news-email">Email address</label><input id="news-email" type="email" name="email" placeholder="Your email address" required><button>Subscribe ↗</button><div class="form-result" aria-live="polite"></div></form></section>';
const shopPage=(category='',isNew=false,search='')=>{let products=store.products.filter(p=>(!category||p.category.toLowerCase()===category.toLowerCase())&&(!isNew||p.is_new)&&(!search||(p.name+' '+p.category+' '+p.colours.map(c=>c.name).join(' ')).toLowerCase().includes(search.toLowerCase())));const params=new URLSearchParams(location.hash.split('?')[1]||'');let color=params.get('colour'),size=params.get('size'),max=params.get('max'),min=params.get('min'),availability=params.get('availability'),sort=params.get('sort')||'relevance';products=products.filter(p=>(!color||p.colours.some(c=>c.name.toLowerCase()===color.toLowerCase()))&&(!size||p.sizes.includes(size))&&(!max||p.price<=Number(max))&&(!min||p.price>=Number(min))&&(!availability||p.colours.some(c=>p.sizes.some(s=>stockFor(p,c.name,s)>0))===(availability==='available')));if(sort==='low')products.sort((a,b)=>a.price-b.price);if(sort==='high')products.sort((a,b)=>b.price-a.price);if(sort==='new')products.sort((a,b)=>Number(b.is_new)-Number(a.is_new));return '<main class="page"><div class="page-header"><div><span class="eyebrow">ROWAN & REGENT</span><h1 class="page-title">'+(search?'SEARCH RESULTS':isNew?'NEW ARRIVALS':category?esc(category.toUpperCase()):'SHOP ALL')+'</h1></div><p>Considered essentials. Enduring silhouettes. Pieces to make your own.</p></div><div class="filter-row"><select data-filter="category" aria-label="Filter category"><option value="">All categories</option>'+CATS.map(c=>'<option '+(category===c?'selected':'')+'>'+c+'</option>').join('')+'</select><select data-filter="colour" aria-label="Filter colour"><option value="">All colours</option>'+[...new Set(store.products.flatMap(p=>p.colours.map(c=>c.name)))].map(c=>'<option '+(color===c?'selected':'')+'>'+esc(c)+'</option>').join('')+'</select><select data-filter="size" aria-label="Filter size"><option value="">All sizes</option>'+[...new Set(store.products.flatMap(p=>p.sizes))].map(s=>'<option '+(size===s?'selected':'')+'>'+esc(s)+'</option>').join('')+'</select><select data-filter="min" aria-label="Minimum price"><option value="">Any minimum</option><option value="1500" '+(min==='1500'?'selected':'')+'>From ₹1,500</option><option value="2000" '+(min==='2000'?'selected':'')+'>From ₹2,000</option></select><select data-filter="max" aria-label="Maximum price"><option value="">Any price</option><option value="2000" '+(max==='2000'?'selected':'')+'>Under ₹2,000</option><option value="2500" '+(max==='2500'?'selected':'')+'>Under ₹2,500</option><option value="3000" '+(max==='3000'?'selected':'')+'>Under ₹3,000</option></select><select data-filter="availability" aria-label="Availability"><option value="">Any availability</option><option value="available" '+(availability==='available'?'selected':'')+'>In stock</option><option value="unavailable" '+(availability==='unavailable'?'selected':'')+'>Unavailable</option></select><select data-filter="sort" aria-label="Sort products"><option value="relevance">Sort: relevance</option><option value="low" '+(sort==='low'?'selected':'')+'>Price: low to high</option><option value="high" '+(sort==='high'?'selected':'')+'>Price: high to low</option><option value="new" '+(sort==='new'?'selected':'')+'>Newest</option></select><span class="results-count">'+products.length+' pieces</span></div>'+(products.length?'<div class="product-grid">'+products.map(card).join('')+'</div>':'<div class="empty"><h2>No pieces found</h2><p>Try another filter or browse the complete collection.</p><a class="button" href="'+href('shop')+'">Clear filters</a></div>')+'</main>'};
const productPage=id=>{const p=store.products.find(x=>x.id===id);if(!p)return articlePage('not-found');const selected=store.selected?.id===id?store.selected:{id,c:p.colours[0].name,s:p.sizes[0],q:1};store.selected=selected;const available=stockFor(p,selected.c,selected.s)>0;const related=store.products.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4);return '<main class="page"><div class="breadcrumbs"><a href="'+href('shop')+'">SHOP</a> / <a href="'+href('shop/'+p.category)+'">'+esc(p.category.toUpperCase())+'</a> / '+esc(p.name.toUpperCase())+'</div><section class="product-detail"><div><img class="detail-image" data-zoom src="'+esc(p.image)+'" alt="'+esc(p.name)+' in '+esc(selected.c)+'" title="Click to zoom"></div><div class="detail-copy"><span class="eyebrow">'+esc(p.category)+' · ROWAN & REGENT</span><h1>'+esc(p.name)+'</h1><div class="detail-price">'+money(p.price)+'</div><p class="detail-description">'+esc(p.description)+'</p><div class="variant-label">Colour · '+esc(selected.c)+'</div><div class="color-options">'+p.colours.map(c=>'<button class="color-option '+(selected.c===c.name?'selected':'')+'" data-color="'+esc(c.name)+'"><span class="swatch" style="display:inline-block;vertical-align:middle;margin-right:7px;background:'+esc(c.hex)+'"></span>'+esc(c.name)+'</button>').join('')+'</div><div class="variant-label">'+(p.category==='Trousers'||p.category==='Accessories'?'Waist / size':'Size')+' · '+esc(selected.s)+' <a class="text-link" style="float:right" href="'+href('size-guide')+'">Size guide</a></div><div class="size-options">'+p.sizes.map(s=>'<button class="size-option '+(selected.s===s?'selected':'')+'" data-size="'+esc(s)+'" '+(stockFor(p,selected.c,s)<1?'disabled':'')+'>'+esc(s)+'</button>').join('')+'</div><div class="detail-meta">'+(available?'Sample inventory · available':'This variant is currently unavailable')+'<br>Shipping '+money(store.settings.shippingFee)+' · complimentary from '+money(store.settings.freeShippingThreshold)+'</div><div class="detail-actions"><div class="quantity"><button data-q="-1" aria-label="Decrease quantity">−</button><span>'+selected.q+'</span><button data-q="1" aria-label="Increase quantity">+</button></div><button class="button" data-add="'+p.id+'" '+(!available?'disabled':'')+'>Add to bag</button><button class="button outline" data-buy="'+p.id+'" '+(!available?'disabled':'')+'>Buy now</button></div><div style="margin-top:14px"><button class="text-link" data-wish="'+p.id+'">'+(store.wish.has(p.id)?'♥ SAVED TO WISHLIST':'♡ ADD TO WISHLIST')+'</button></div><div class="detail-meta">A considered piece for smart-casual and everyday dressing. Product care guidance is not specified.</div></div></section>'+(related.length?'<section class="section" style="padding-inline:0"><div class="section-head"><h2>YOU MAY ALSO LIKE</h2></div><div class="product-grid">'+related.map(card).join('')+'</div></section>':'')+'</main>'};
const summary=()=>{const t=cartMath();return '<aside class="summary"><h2>Order summary</h2><div class="summary-row"><span>Subtotal</span><span>'+money(t.subtotal)+'</span></div><div class="summary-row"><span>Shipping</span><span>'+(t.shipping?money(t.shipping):t.subtotal?'Complimentary':money(0))+'</span></div><div class="summary-row total"><span>Total</span><span>'+money(t.total)+'</span></div><p style="font-size:10px;color:#68645d">'+(t.subtotal<store.settings.freeShippingThreshold?'Complimentary shipping from '+money(store.settings.freeShippingThreshold):'Complimentary shipping applied')+'</p><a class="button" href="'+href('checkout')+'">Proceed to checkout</a></aside>'};
const cartPage=()=>'<main class="page"><div class="page-header"><div><span class="eyebrow">YOUR SELECTION</span><h1 class="page-title">THE SHOPPING BAG</h1></div><a class="text-link" href="'+href('shop')+'">Continue shopping</a></div>'+(store.cart.length?'<div class="cart-layout"><div>'+store.cart.map(x=>{const p=lineProduct(x.productId);if(!p)return'';return '<article class="cart-line"><a href="'+href('product/'+p.id)+'"><img src="'+esc(p.image)+'" alt="'+esc(p.name)+'"></a><div><a href="'+href('product/'+p.id)+'"><h3>'+esc(p.name)+'</h3></a><p>'+esc(x.colour)+' · '+esc(x.size)+'</p><div class="quantity" style="width:max-content;margin:8px 0"><button data-cartqty="-1" data-key="'+esc(keyLine(x))+'">−</button><span>'+x.quantity+'</span><button data-cartqty="1" data-key="'+esc(keyLine(x))+'">+</button></div><button class="remove" data-remove="'+esc(keyLine(x))+'">Remove</button></div><span>'+money(p.price*x.quantity)+'</span></article>'}).join('')+'</div>'+summary()+'</div>':'<div class="empty"><h2>Your bag is at ease.</h2><p>There is nothing in your shopping bag just yet.</p><a class="button" href="'+href('shop')+'">Explore the collection</a></div>')+'</main>';
const keyLine=x=>x.productId+'|'+x.colour+'|'+x.size;
const checkout=()=>{const t=cartMath(), recent=JSON.parse(sessionStorage.getItem('rr-order')||'null');if(!store.cart.length&&recent)return confirmation(recent);if(!store.cart.length)return '<main class="page"><div class="empty"><h2>Your bag is empty.</h2><a class="button" href="'+href('shop')+'">Return to the collection</a></div></main>';if(!store.me.authenticated)return '<main class="page"><span class="eyebrow">SECURE CHECKOUT</span><h1 class="page-title">YOUR ORDER</h1><div class="notice" style="margin-top:25px">Sign in to your Websim account to submit an order. This shop uses Websim account authentication and does not collect or store passwords.</div><p><a class="button" style="margin-top:18px" href="https://websim.com">Sign in to Websim</a> <a class="text-link" href="'+href('account')+'">Account details</a></p></main>';
return '<main class="page"><span class="eyebrow">SECURE CHECKOUT · MANUAL UPI</span><h1 class="page-title">REVIEW & CHECK OUT</h1><div class="notice" style="margin-top:18px">Catalogue quantities are sample inventory. Please confirm availability with the store before relying on stock status.</div><div class="checkout-layout" style="margin-top:35px"><form id="checkout-form"><section class="checkout-step"><h2>01 · Your details</h2><div class="form-grid"><div class="field"><label>Full name</label><input name="name" required value="'+esc(store.me.username||'')+'"></div><div class="field"><label>Email address</label><input name="email" type="email" required></div><div class="field full"><label>Mobile number</label><input name="phone" inputmode="numeric" pattern="[0-9]{10}" minlength="10" maxlength="10" required placeholder="10-digit Indian mobile number"></div></div></section><section class="checkout-step"><h2>02 · Shipping address</h2><div class="form-grid"><div class="field full"><label>House / building and street</label><input name="street" required></div><div class="field full"><label>Locality</label><input name="locality" required></div><div class="field"><label>City</label><input name="city" required></div><div class="field"><label>State</label><input name="state" required></div><div class="field"><label>PIN code</label><input name="pin" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required></div><div class="field full"><label>Delivery instructions · optional</label><textarea name="instructions" maxlength="300"></textarea></div></div></section><section class="checkout-step"><h2>03 · Payment</h2><div class="notice">Manual UPI payment · Scan and pay using any compatible UPI app. After completing the payment, return here and submit your order for payment confirmation. A QR scan is not proof of payment.</div><div id="payment-panel"></div></section><div id="checkout-error" class="error" aria-live="polite"></div><button class="button" id="place-order" type="submit">Continue to secure payment</button></form><div><div class="summary"><h2>Order review</h2>'+store.cart.map(x=>{const p=lineProduct(x.productId);return '<div class="summary-row"><span>'+esc(p?.name||'')+'<br><small>'+esc(x.size)+' · '+esc(x.colour)+' × '+x.quantity+'</small></span><span>'+money((p?.price||0)*x.quantity)+'</span></div>'}).join('')+'<div class="summary-row"><span>Subtotal</span><span>'+money(t.subtotal)+'</span></div><div class="summary-row"><span>Shipping</span><span>'+money(t.shipping)+'</span></div><div class="summary-row total"><span>Total payable</span><span>'+money(t.total)+'</span></div></div></div></div></main>'};
const confirmation=o=>{const lines=o.items.map(x=>x.name+' · '+x.size+' / '+x.colour+' × '+x.quantity+' · '+money(x.price)+' each').join('\n');const msg='Hello ROWAN & REGENT,\nI am confirming my order.\nName: '+o.customer.name+'\nOrder: '+o.id+'\nItems:\n'+lines+'\nSubtotal: '+money(o.subtotal)+'\nShipping: '+money(o.shipping)+'\nTotal: '+money(o.total)+'\nShip to: '+o.address.city+', '+o.address.pin+'\nPayment: '+o.paymentStatus+'\n(Customer will send this message manually.)';return '<main class="page"><div class="empty"><span class="eyebrow">ORDER RECEIVED</span><h1 class="page-title">THANK YOU, '+esc(o.customer.name.split(' ')[0].toUpperCase())+'.</h1><p>Your order <strong>'+esc(o.id)+'</strong> has been submitted. Your manual UPI payment is <strong>'+esc(o.paymentStatus)+'</strong>.</p><p>Payee: Saksham Pasrija · Total: '+money(o.total)+'</p><div class="notice" style="max-width:600px;margin:20px auto">Payment has not been automatically confirmed. Your reference, if provided, remains unverified until the store owner checks it.</div><div class="summary" style="max-width:600px;margin:20px auto;text-align:left"><h2>Items</h2>'+o.items.map(x=>'<div class="summary-row"><span>'+esc(x.name)+' · '+esc(x.size)+' / '+esc(x.colour)+' × '+x.quantity+'</span><span>'+money(x.price*x.quantity)+'</span></div>').join('')+'<div class="summary-row total"><span>Total</span><span>'+money(o.total)+'</span></div><p>'+esc(o.address.street)+', '+esc(o.address.locality)+', '+esc(o.address.city)+', '+esc(o.address.state)+' '+esc(o.address.pin)+'</p></div><a class="button" target="_blank" rel="noopener" href="https://wa.me/919817322096?text='+encodeURIComponent(msg)+'">Confirm order on WhatsApp</a><p style="font-size:10px">WhatsApp opens with a message for you to review and send.</p><a class="text-link" href="'+href('orders')+'">View your orders</a></div></main>'};
const account=()=>'<main class="page"><div class="page-header"><div><span class="eyebrow">YOUR ACCOUNT</span><h1 class="page-title">WELCOME, '+esc(store.me.username||'GUEST')+'.</h1></div></div>'+(store.me.authenticated?'<div class="account-grid"><nav class="account-nav"><a href="'+href('account')+'">Overview</a><a href="'+href('orders')+'">Order history</a><a href="'+href('wishlist')+'">Wishlist</a><a href="https://websim.com">Account settings ↗</a></nav><div><div class="notice">Your identity and account security are managed by Websim. Passwords are not collected by this storefront.</div><h2 style="font:500 30px var(--serif);margin-top:28px">Saved addresses</h2>'+store.addresses.map(a=>'<article class="notice" style="margin:10px 0"><strong>'+esc(a.label)+'</strong><br>'+esc(a.street)+', '+esc(a.locality)+', '+esc(a.city)+', '+esc(a.state)+' '+esc(a.pin)+'<br><button class="remove" data-address-delete="'+esc(a.id)+'">Remove address</button></article>').join('')+'<form id="address-form" class="form-grid" style="margin:18px 0"><div class="field"><label>Address label</label><input name="label" placeholder="Home" required maxlength="40"></div><div class="field"><label>PIN code</label><input name="pin" inputmode="numeric" pattern="[0-9]{6}" required maxlength="6"></div><div class="field full"><label>House / street</label><input name="street" required></div><div class="field full"><label>Locality</label><input name="locality" required></div><div class="field"><label>City</label><input name="city" required></div><div class="field"><label>State</label><input name="state" required></div><button class="button">Save address</button><div class="form-result" aria-live="polite"></div></form><h2 style="font:500 30px var(--serif);margin-top:28px">Recent orders</h2>'+orderList(store.orders.slice(0,3))+'</div></div>':'<div class="notice" style="max-width:600px">Sign in to your Websim account to view your own orders and synchronise your wishlist. No storefront password is created or stored.</div><a class="button" style="margin-top:18px" href="https://websim.com">Sign in to Websim</a><p><a class="text-link" href="'+href('signin')+'">Sign in</a> · <a class="text-link" href="'+href('signup')+'">Create account</a> · <a class="text-link" href="'+href('forgot-password')+'">Forgot password</a></p><p><a class="text-link" href="'+href('orders')+'">Order history</a></p>')+'</main>';
const orderList=orders=>orders.length?'<div>'+orders.map(o=>'<article style="padding:16px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:16px"><div><strong>'+esc(o.id)+'</strong><div style="font-size:11px;color:#777">'+new Date(o.createdAt).toLocaleDateString('en-IN')+' · '+esc(o.orderStatus)+'</div><div style="font-size:11px">Payment: '+esc(o.paymentStatus)+'</div></div><div style="text-align:right">'+money(o.total)+'<br><a class="text-link" href="'+href('order/'+o.id)+'">Details</a></div></article>').join('')+'</div>':'<div class="empty"><h2>No orders yet.</h2><a class="text-link" href="'+href('shop')+'">Explore the collection</a></div>';
const wishlistPage=()=>{const items=store.products.filter(p=>store.wish.has(p.id));return '<main class="page"><span class="eyebrow">SAVED FOR LATER</span><h1 class="page-title">YOUR WISHLIST</h1>'+(items.length?'<div class="product-grid" style="margin-top:35px">'+items.map(card).join('')+'</div>':'<div class="empty"><h2>Keep the pieces you love close.</h2><a class="button" href="'+href('shop')+'">Discover the collection</a></div>')+'</main>'};
const orderPage=id=>{const o=store.orders.find(x=>x.id===id);if(!o)return '<main class="page"><div class="empty"><h2>Order not found.</h2><p>Order details are visible only to their signed-in customer.</p><a href="'+href('orders')+'">Order history</a></div></main>';return '<main class="page"><span class="eyebrow">ORDER DETAILS</span><h1 class="page-title">'+esc(o.id)+'</h1><p>'+new Date(o.createdAt).toLocaleString('en-IN')+' · '+esc(o.orderStatus)+'</p><div class="notice">Payment status: '+esc(o.paymentStatus)+(o.transactionReference?'<br>Reference submitted: '+esc(o.transactionReference)+' · unverified':'')+'</div><div class="summary" style="max-width:650px;margin-top:22px">'+o.items.map(x=>'<div class="summary-row"><span>'+esc(x.name)+' · '+esc(x.size)+' / '+esc(x.colour)+' × '+x.quantity+'</span><span>'+money(x.price*x.quantity)+'</span></div>').join('')+'<div class="summary-row"><span>Subtotal</span><span>'+money(o.subtotal)+'</span></div><div class="summary-row"><span>Shipping</span><span>'+money(o.shipping)+'</span></div><div class="summary-row total"><span>Total</span><span>'+money(o.total)+'</span></div></div><a class="text-link" href="'+href('orders')+'">Back to orders</a></main>'};
const articleData={about:['OUR STORY','Considered by nature. Refined by choice.','ROWAN & REGENT is built around the belief that personal style does not need to be loud. Our fictional label brings together a considered edit of wardrobe essentials, inspired by heritage menswear, classic tailoring and the enduring appeal of simplicity. We make no claims beyond the pieces and details shown in this catalogue.'], 'size-guide':['SIZE GUIDE','Find your considered fit.','Choose from the sizes listed on each product page. Sizing varies by product and customer measurements. Garment measurements are not yet available, so we will not invent them. If you are between sizes or need advice, contact sakshampasrija@gmail.com.'],contact:['CONTACT','We are here to help.','Email sakshampasrija@gmail.com or call 9817322096. For order-specific support, please sign in and include your order number.'],faq:['FREQUENTLY ASKED QUESTIONS','A few useful details.','Orders are placed online, reviewed at checkout and paid by manual UPI QR. Submitted payment references are unverified until the store owner checks them. Sign in to view your order history. Shipping is ₹99 below ₹3,000 and complimentary from ₹3,000. Delivery estimates have not been confirmed.'],shipping:['SHIPPING','A considered delivery.','Shipping costs ₹99 for orders below ₹3,000 and is complimentary on orders of ₹3,000 or more. Delivery estimates have not yet been confirmed. Check your order confirmation or contact sakshampasrija@gmail.com.'],returns:['RETURNS & REFUNDS','Our policy is being finalised.','The final commercial return, exchange, refund and cancellation terms require store-owner approval. Please contact sakshampasrija@gmail.com before ordering. We do not promise a return window or refund timeline at this time.'],privacy:['PRIVACY POLICY','Your information.','Orders, support enquiries and newsletter subscriptions are stored in the project database and associated with your authenticated Websim account. Account identity is provided by Websim. Payment card details and passwords are not collected by this storefront. Contact sakshampasrija@gmail.com with privacy enquiries.'],terms:['TERMS & CONDITIONS','A transparent first edition.','Catalogue prices are shown in INR. Orders submitted with manual UPI payment remain awaiting verification until an authorised administrator checks payment. The shop does not provide automatic payment confirmation. Final return and cancellation terms are being finalised. Contact sakshampasrija@gmail.com with questions.']};
const articlePage=key=>{const d=articleData[key];if(!d)return '<main class="page"><div class="empty"><h1 class="page-title">PAGE NOT FOUND</h1><a class="button" href="'+href('shop')+'">Browse the collection</a></div></main>';return '<main class="page"><div class="policy-copy"><span class="eyebrow">ROWAN & REGENT</span><h1 class="page-title">'+d[0]+'</h1><h2>'+d[1]+'</h2><p>'+(key==='returns'?(store.settings.returnsPolicy||d[2]):key==='shipping'?'Shipping costs '+money(store.settings.shippingFee)+' below '+money(store.settings.freeShippingThreshold)+' and is complimentary at or above that amount. '+(store.settings.deliveryEstimate||'Delivery estimates have not yet been confirmed.')+' Check your order confirmation or contact support.':key==='faq'?'Manual UPI checkout is available. Shipping costs '+money(store.settings.shippingFee)+' below '+money(store.settings.freeShippingThreshold)+' and is complimentary at or above that amount. Delivery estimates are not confirmed.':d[2])+'</p>'+(key==='faq'?'<h2>How do I find my size?</h2><p>Use sizes listed on the product and see our <a href="'+href('size-guide')+'">size guide</a>. Product measurements are not yet available.</p><h2>How do I reach the team?</h2><p>Write to <a href="mailto:sakshampasrija@gmail.com">sakshampasrija@gmail.com</a>.</p>':'')+(key==='contact'?'<form id="support-form" style="max-width:500px;margin-top:30px"><h2>Write to the team</h2><div class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field full"><label>Message</label><textarea name="message" required maxlength="1500"></textarea></div></div><button class="button" style="margin-top:14px">Send enquiry</button><div class="form-result" aria-live="polite"></div></form>':'')+'</div></main>'};
const adminPage=()=>{if(!store.me.isOwner)return '<main class="page"><div class="empty"><h1 class="page-title">OWNER ACCESS ONLY</h1><p>Product and order administration is restricted by server-side project-owner identity.</p></div></main>';if(!store.admin)return '<main class="page"><h1 class="page-title">REGENT OFFICE</h1><p>'+esc(store.adminError||'Loading store records…')+'</p></main>';const a=store.admin,tab=store.adminTab||'products';let content='';if(tab==='products')content='<form id="product-create" class="notice"><strong>Add a product</strong><div class="form-grid" style="margin-top:12px"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Category</label><select name="category">'+CATS.map(x=>'<option>'+x+'</option>').join('')+'</select></div><div class="field"><label>Price · INR</label><input name="price" type="number" min="1" required></div><div class="field"><label>Image path</label><select name="image"><option>assets/shirts.png</option><option>assets/knitwear.png</option><option>assets/trousers.png</option><option>assets/accessories.png</option></select></div><div class="field full"><label>Description</label><input name="description" required></div><div class="field"><label>Colours · comma separated</label><input name="colours" placeholder="Ivory, Navy" required></div><div class="field"><label>Sizes · comma separated</label><input name="sizes" placeholder="S, M, L" required></div></div><button class="button small" style="margin-top:12px">Create product</button><div class="form-result"></div></form><div class="table-scroll"><table class="admin-table"><thead><tr><th>Product</th><th>Price</th><th>Variant stock</th><th>Save</th><th>Remove</th></tr></thead><tbody>'+store.products.map(p=>'<tr><td><input data-name="'+p.id+'" value="'+esc(p.name)+'"><br><small>'+esc(p.category)+'</small></td><td><input data-price="'+p.id+'" type="number" min="1" value="'+p.price+'"></td><td>'+p.colours.flatMap(c=>p.sizes.map(s=>'<label style="display:inline-block;margin:2px;font-size:9px">'+esc(c.name)+' · '+esc(s)+'<br><input data-stock-id="'+p.id+'" data-stock-key="'+esc(c.name+'|'+s)+'" type="number" min="0" value="'+stockFor(p,c.name,s)+'"></label>')).join('')+'</td><td><button class="button small" data-admin-save="'+p.id+'">Save</button></td><td><button class="text-link" data-admin-delete="'+p.id+'">Delete</button></td></tr>').join('')+'</tbody></table></div>';
if(tab==='orders')content='<div class="table-scroll"><table class="admin-table"><thead><tr><th>Order</th><th>Customer</th><th>Total / payment</th><th>Status</th><th>Verify</th></tr></thead><tbody>'+a.orders.map(o=>'<tr><td>'+esc(o.id)+'<br><small>'+new Date(o.createdAt).toLocaleDateString()+'</small></td><td>'+esc(o.customer.name)+'<br>'+esc(o.customer.email)+'<br>'+esc(o.customer.phone)+'</td><td>'+money(o.total)+'<br>'+esc(o.paymentStatus)+'<br><small>UPI ref: '+esc(o.transactionReference||'not provided')+'</small></td><td><select data-order-status="'+o.id+'">'+['Received','Processing','Shipped','Delivered','Cancelled'].map(x=>'<option '+(o.orderStatus===x?'selected':'')+'>'+x+'</option>').join('')+'</select></td><td><button class="button small" data-verify="'+o.id+'">Verify payment</button></td></tr>').join('')+'</tbody></table></div>';
if(tab==='subscribers')content='<h2 style="font:500 30px var(--serif)">Newsletter subscribers</h2>'+a.subscribers.map(s=>'<p>'+esc(s.email)+' · '+new Date(s.created_at).toLocaleDateString()+'</p>').join('');
if(tab==='support')content='<h2 style="font:500 30px var(--serif)">Customer enquiries</h2>'+a.support.map(s=>'<article class="notice" style="margin:12px 0"><strong>'+esc(s.name)+' · '+esc(s.email)+'</strong><p>'+esc(s.message)+'</p></article>').join('');
if(tab==='settings')content='<form id="store-settings" class="form-grid"><div class="field full"><label>Announcement</label><input name="announcement" value="'+esc(a.settings.announcement)+'"></div><div class="field"><label>Shipping fee</label><input name="shippingFee" type="number" value="'+a.settings.shippingFee+'"></div><div class="field"><label>Free shipping threshold</label><input name="freeShippingThreshold" type="number" value="'+a.settings.freeShippingThreshold+'"></div><div class="field full"><label>Returns policy</label><textarea name="returnsPolicy">'+esc(a.settings.returnsPolicy||'')+'</textarea></div><div class="field full"><label>Delivery estimate</label><input name="deliveryEstimate" value="'+esc(a.settings.deliveryEstimate||'')+'"></div><div class="field full"><label>Instagram URL · optional</label><input name="instagramUrl" value="'+esc(a.settings.instagramUrl||'')+'"></div><button class="button">Save settings</button><div class="form-result"></div></form>';
return '<main class="page"><span class="eyebrow">OWNER WORKSPACE</span><h1 class="page-title">THE REGENT OFFICE</h1><div class="admin-tabs">'+[['products','Products & inventory'],['orders','Orders'],['subscribers','Subscribers'],['support','Enquiries'],['settings','Store settings']].map(([k,n])=>'<button class="'+(tab===k?'active':'')+'" data-admin-tab="'+k+'">'+n+'</button>').join('')+'</div>'+content+'</main>'};
const page=()=>{const [raw,query='']=location.hash.replace(/^#\/?/,'').split('?');const seg=raw.split('/').filter(Boolean);const route=seg[0]||'home';store.query=new URLSearchParams(query).get('q')||'';if(route==='home')return home();if(route==='shop')return shopPage(seg[1]||'',false);if(route==='new')return shopPage('',true);if(route==='search')return shopPage('',false,store.query);if(route==='product')return productPage(seg[1]);if(route==='cart')return cartPage();if(route==='checkout')return checkout();if(route==='confirmation'){const o=JSON.parse(sessionStorage.getItem('rr-order')||'null');return o?confirmation(o):articlePage('not-found')}if(route==='wishlist')return wishlistPage();if(route==='account')return account();if(['signin','signup','forgot-password','reset-password'].includes(route))return '<main class="page"><span class="eyebrow">YOUR ACCOUNT</span><h1 class="page-title">'+(route==='signup'?'CREATE AN ACCOUNT':route==='forgot-password'||route==='reset-password'?'ACCOUNT RECOVERY':'SIGN IN')+'</h1><div class="notice" style="max-width:620px;margin-top:25px">Account authentication is provided by Websim. This storefront does not create email/password accounts or collect passwords. Sign in to Websim, then return to your account.</div><a class="button" style="margin-top:18px" href="https://websim.com">Continue to Websim</a></main>';if(route==='orders')return '<main class="page"><span class="eyebrow">YOUR ACCOUNT</span><h1 class="page-title">ORDER HISTORY</h1>'+(store.me.authenticated?orderList(store.orders):'<div class="notice">Sign in to your Websim account to view private order history.</div>')+'</main>';if(route==='order')return orderPage(seg[1]);if(route==='admin')return adminPage();return articlePage(route)};
const render=()=>{app.innerHTML=shell(page());if(store.me.isOwner)document.querySelector('.page .eyebrow')?.insertAdjacentHTML('afterend','<p class="notice" style="margin-top:18px">Initial catalogue inventory is sample demo data. Reconcile each variant in the owner workspace before accepting real orders.</p>');attachPaymentPanel();if(location.hash.includes('/admin')&&store.me.isOwner&&!store.admin&&!store.adminLoading)loadAdmin();document.title=(location.hash.split('/')[1]?.split('?')[0]||'Home').replace(/-/g,' ').replace(/^./,x=>x.toUpperCase())+' | Rowan & Regent';};
let pendingOrder=null;
const loadAdmin=async()=>{store.adminLoading=true;try{store.admin=await api('/api/admin')}catch(e){store.adminError=e.message}finally{store.adminLoading=false;render()}};
const attachPaymentPanel=()=>{const box=document.querySelector('#payment-panel');if(!box||!pendingOrder)return;const o=pendingOrder;const uri='upi://pay?pa=pasrijasaksham777-1@okicici&pn=Saksham%20Pasrija&aid=uGICAgMDvnp6kaQ&am='+o.total+'&cu=INR';box.innerHTML='<div class="qr-wrap"><img src="https://api.qrserver.com/v1/create-qr-code/?size=260x260&margin=8&data='+encodeURIComponent(uri)+'" alt="UPI payment QR code for '+money(o.total)+'"><div class="pay-info"><strong>'+money(o.total)+'</strong><br>Payee: Saksham Pasrija<br>UPI ID: pasrijasaksham777-1@okicici<br>Order reference: '+esc(o.id)+'</div><div style="display:flex;justify-content:center;gap:10px;margin-top:14px;flex-wrap:wrap"><button type="button" class="text-link" data-copy-upi>Copy UPI ID</button><button type="button" class="text-link" data-copy-amount>Copy amount</button><a class="text-link" href="'+uri+'">Pay with UPI app</a></div></div><div class="field"><label>UPI transaction / reference number · optional</label><input id="transaction-reference" maxlength="80" placeholder="Customer-entered, unverified"></div><p class="notice">Order '+esc(o.id)+' is awaiting payment verification. Your reference is supporting information only; payment is not automatically confirmed.</p><button type="button" class="button" data-paid>I have paid — submit order</button>';const submit=document.querySelector('#place-order');if(submit)submit.hidden=true;};
const loadCatalog=async()=>{const d=await api('/api/products'),order=['regent-oxford','riviera-linen','heritage-polo','regent-quarter-zip','clubhouse-knit','savile-trouser','estate-chino','country-overshirt','heritage-belt','regent-loafer'];store.products=[...d.products].sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));store.settings={...store.settings,...d.settings};};
const saveAdmin=async()=>{store.admin=await api('/api/admin');await loadCatalog();render()};
const chatAnswer=input=>{const q=input.toLowerCase(),p=store.products.find(x=>q.includes(x.name.toLowerCase())||x.name.toLowerCase().split(' ').slice(1).join(' ').length>7&&q.includes(x.name.toLowerCase().split(' ').slice(1).join(' ')));if(/track|order status|payment confirm|did.*pay|payment status/.test(q)){const id=input.match(/RR-[A-Z0-9-]+/i)?.[0];if(!store.me.authenticated)return 'Please sign in to your Websim account before asking about a specific order. I cannot access another customer’s information.';if(!id)return 'Please share your order number. I can only check orders belonging to your signed-in account.';const o=store.orders.find(x=>x.id.toLowerCase()===id.toLowerCase());return o?'Order '+o.id+' is '+o.orderStatus+'. Payment: '+o.paymentStatus+'. A customer-entered UPI reference is not proof of payment.':'I could not find that order in your account. Please check the order number or contact sakshampasrija@gmail.com.'}if(/price|sell|catalog|collection|products/.test(q)&&!p)return store.products.map(x=>x.name+' — '+money(x.price)).join(' · ');if(p&&/size|colour|color|available|stock|price/.test(q))return p.name+' is '+money(p.price)+'. Colours: '+p.colours.map(x=>x.name).join(', ')+'. Listed sizes: '+p.sizes.join(', ')+'. Current available variants are shown on the product page: '+location.origin+'/#/product/'+p.id+'.';if(/colour|color/.test(q))return 'Which piece are you considering? Tell me its name and I can check the catalogue colours.';if(/\bsize\b|\bfit\b|measurement/.test(q))return 'Sizing varies by product. Please use the sizes listed on each product page and our size guide. Garment measurements are not available, so I won’t estimate them. I can help if you share a product name.';if(/old.money/.test(q))return 'Here, old-money style refers to restrained palettes, clean silhouettes and considered layering; it is an aesthetic, not a claim about wealth.';if(/outfit|style|wear|dinner|date|college|wedding|office|vacation|linen|pair/.test(q)){if(/linen|summer|vacation/.test(q))return 'For summer dressing, consider the Riviera Linen Shirt with beige or navy trousers. Keep the palette restrained and the silhouette relaxed.';if(/polo/.test(q))return 'The Heritage Polo pairs naturally with tailored trousers or clean chinos. The Savile Pleated Trouser and Estate Chino are in the collection.';if(/layer|cold|overshirt/.test(q))return 'For layering, consider the Regent Quarter-Zip or Country House Overshirt over a neutral base with simple trousers.';return 'A considered outfit could pair the Regent Oxford Shirt with the Estate Chino, or a Heritage Polo with the Savile Pleated Trouser. Ivory, navy, olive, camel and charcoal work well together. Choose what suits the occasion and your comfort.'}if(/address|change.*delivery/.test(q))return 'For a submitted order, please contact sakshampasrija@gmail.com with your order number. I cannot change an address on your behalf.';if(/ship|delivery|shipping/.test(q)){const shipping='Shipping is '+money(store.settings.shippingFee)+' below '+money(store.settings.freeShippingThreshold)+' and complimentary at or above that amount. Delivery estimates are not yet confirmed; check your order details or contact support.';return /return|refund|exchange/.test(q)?shipping+' '+(store.settings.returnsPolicy||'Returns details are being finalised; contact sakshampasrija@gmail.com.'):shipping;}if(/return|refund|cancel|exchange/.test(q))return store.settings.returnsPolicy||'Detailed return, exchange, refund and cancellation terms are being finalised. Please contact sakshampasrija@gmail.com.';if(/upi|pay|payment|qr/.test(q))return 'Payment is by manual UPI QR to pasrijasaksham777-1@okicici, payee Saksham Pasrija. The QR contains your calculated checkout total. Your order remains awaiting verification until the store owner checks payment. Never share your UPI PIN.';if(/order|checkout|buy/.test(q))return 'Choose a piece and variant, add it to your bag, enter delivery details, review the total and submit. Manual UPI orders remain awaiting payment verification.';if(/care|wash|launder/.test(q))return 'Product-specific care instructions are not available in the confirmed catalogue yet. Please contact sakshampasrija@gmail.com before caring for a particular item.';if(/contact|support|phone|email|damaged|address/.test(q))return 'Please contact sakshampasrija@gmail.com or call 9817322095. For an order issue, include your order number. Please do not share passwords, OTPs or your UPI PIN.';return "I don't have a confirmed answer to that yet. Please contact our support team at sakshampasrija@gmail.com or 9817322096."};
const sendChat=text=>{const clean=text.trim();if(!clean)return;store.messages.push({who:'user',text:clean},{who:'bot',text:chatAnswer(clean)});render();const messages=document.querySelector('#chat-messages');if(messages)messages.scrollTop=messages.scrollHeight;};
app.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(e.target.matches('[data-zoom]')){e.target.classList.toggle('zoom');return}if(!b)return;try{
if(b.hasAttribute('data-menu')){store.menuOpen=!store.menuOpen;render();return}
if(b.hasAttribute('data-search')){store.searchOpen=!store.searchOpen;render();document.querySelector('[name=q]')?.focus();return}
if(b.hasAttribute('data-chat')){store.chat=!store.chat;render();return}
if(b.dataset.prompt){sendChat(b.dataset.prompt);return}
if(b.dataset.wish){await saveWish(b.dataset.wish);return}
if(b.dataset.quick){const p=lineProduct(b.dataset.quick),v=p.colours.map(c=>({c,s:p.sizes.find(s=>stockFor(p,c.name,s)>0)})).find(x=>x.s);if(v)addCart(p,v.c.name,v.s);else alert('This piece is currently unavailable.');return}
if(b.dataset.color){const p=lineProduct(location.hash.split('/')[2]?.split('?')[0]);if(p){const s=p.sizes.find(x=>stockFor(p,b.dataset.color,x)>0)||p.sizes[0];store.selected={id:p.id,c:b.dataset.color,s,q:store.selected?.id===p.id?store.selected.q:1};render()}return}
if(b.dataset.size){const id=location.hash.split('/')[2]?.split('?')[0],p=lineProduct(id),old=store.selected?.id===id?store.selected:null;store.selected={id,c:old?.c||p.colours[0].name,s:b.dataset.size,q:old?.q||1};render();return}
if(b.dataset.q){const p=lineProduct(location.hash.split('/')[2]?.split('?')[0]),s=store.selected;if(p&&s){s.q=Math.max(1,Math.min(10,s.q+Number(b.dataset.q)));render()}return}
if(b.dataset.add||b.dataset.buy){const p=lineProduct(b.dataset.add||b.dataset.buy),s=store.selected||{c:p.colours[0].name,s:p.sizes[0],q:1};addCart(p,s.c,s.s,s.q);if(b.dataset.buy)location.hash='#/checkout';return}
if(b.dataset.cartqty){const line=store.cart.find(x=>keyLine(x)===b.dataset.key),p=lineProduct(line?.productId);if(line){line.quantity+=Number(b.dataset.cartqty);if(line.quantity<1)store.cart=store.cart.filter(x=>x!==line);else if(line.quantity>stockFor(p,line.colour,line.size)){line.quantity=stockFor(p,line.colour,line.size);alert('Quantity adjusted to available stock.')}persist();render()}return}
if(b.dataset.remove){store.cart=store.cart.filter(x=>keyLine(x)!==b.dataset.remove);persist();render();return}
if(b.dataset.addressDelete){await api('/api/addresses/'+encodeURIComponent(b.dataset.addressDelete),{method:'DELETE'});store.addresses=store.addresses.filter(x=>x.id!==b.dataset.addressDelete);render();return}
if(b.hasAttribute('data-zoom')){b.classList.toggle('zoom');return}
if(b.hasAttribute('data-paid')){b.disabled=true;const ref=document.querySelector('#transaction-reference')?.value||'';const d=await api('/api/orders/'+encodeURIComponent(pendingOrder.id),{method:'PATCH',body:JSON.stringify({transactionReference:ref})});pendingOrder=d.order;store.orders=[pendingOrder,...store.orders.filter(x=>x.id!==pendingOrder.id)];store.cart=[];persist();sessionStorage.setItem('rr-order',JSON.stringify(pendingOrder));sessionStorage.removeItem('rr-checkout-id');location.hash='#/confirmation';return}
if(b.dataset.copyUpi){await navigator.clipboard.writeText('pasrijasaksham777-1@okicici');b.textContent='UPI ID COPIED';return}
if(b.dataset.copyAmount){await navigator.clipboard.writeText(String(pendingOrder?.total||''));b.textContent='AMOUNT COPIED';return}
if(b.dataset.adminTab){store.adminTab=b.dataset.adminTab;render();return}
if(b.dataset.adminSave){const id=b.dataset.adminSave,stock={};document.querySelectorAll('[data-stock-id="'+CSS.escape(id)+'"]').forEach(x=>stock[x.dataset.stockKey]=Math.max(0,Number(x.value)||0));await api('/api/admin/product',{method:'PATCH',body:JSON.stringify({id,name:document.querySelector('[data-name="'+CSS.escape(id)+'"]').value,price:Number(document.querySelector('[data-price="'+CSS.escape(id)+'"]').value),description:lineProduct(id).description,stock})});await saveAdmin();return}
if(b.dataset.adminDelete){if(confirm('Delete this product? Existing order snapshots will remain.')){await api('/api/admin/product?id='+encodeURIComponent(b.dataset.adminDelete),{method:'DELETE'});await saveAdmin()}return}
if(b.dataset.verify){await api('/api/admin/order',{method:'PATCH',body:JSON.stringify({id:b.dataset.verify,verify:true})});await saveAdmin();return}
}catch(error){const target=document.querySelector('#checkout-error')||document.querySelector('.form-result');if(target)target.textContent=error.message;else alert(error.message)}});
app.addEventListener('change',e=>{if(e.target.matches('[data-filter]')){const hash=location.hash,part=hash.slice(2).split('?')[0],params=new URLSearchParams(hash.split('?')[1]||'');if(e.target.dataset.filter==='category'){const cat=e.target.value;location.hash='#/'+(cat?'shop/'+encodeURIComponent(cat):'shop');return}if(e.target.value)params.set(e.target.dataset.filter,e.target.value);else params.delete(e.target.dataset.filter);location.hash='#/'+part+(params.size?'?'+params.toString():'')}if(e.target.matches('[data-order-status]'))api('/api/admin/order',{method:'PATCH',body:JSON.stringify({id:e.target.dataset.orderStatus,orderStatus:e.target.value})}).then(saveAdmin).catch(err=>alert(err.message))});
app.addEventListener('submit',async e=>{const form=e.target;if(form.id==='search-form'){e.preventDefault();location.hash='#/search?q='+encodeURIComponent(new FormData(form).get('q'));return}if(form.id==='chat-form'){e.preventDefault();sendChat(new FormData(form).get('message'));return}if(form.id==='checkout-form'){e.preventDefault();if(pendingOrder)return;const error=document.querySelector('#checkout-error');error.textContent='';const values=Object.fromEntries(new FormData(form));try{const id=sessionStorage.getItem('rr-checkout-id')||'RR-'+new Date().toISOString().slice(2,10).replaceAll('-','')+'-'+crypto.randomUUID().slice(0,8).toUpperCase();sessionStorage.setItem('rr-checkout-id',id);const data=await api('/api/orders',{method:'POST',body:JSON.stringify({id,customer:{name:values.name,email:values.email,phone:values.phone},address:{street:values.street,locality:values.locality,city:values.city,state:values.state,pin:values.pin,instructions:values.instructions},items:store.cart})});pendingOrder=data.order;await loadCatalog();render()}catch(err){error.textContent=err.message}return}
if(form.id==='newsletter-form'){e.preventDefault();const result=form.querySelector('.form-result');try{await api('/api/newsletter',{method:'POST',body:JSON.stringify({email:new FormData(form).get('email')})});result.textContent='Thank you. You are on the list.';result.className='form-result success';form.reset()}catch(err){result.textContent=err.message;result.className='form-result error'}return}
if(form.id==='address-form'){e.preventDefault();try{const d=await api('/api/addresses',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});store.addresses=[d.address,...store.addresses];render()}catch(err){form.querySelector('.form-result').textContent=err.message}return}
if(form.id==='support-form'){e.preventDefault();const result=form.querySelector('.form-result');try{await api('/api/support',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});result.textContent='Your enquiry has been recorded.';result.className='form-result success';form.reset()}catch(err){result.textContent=err.message;result.className='form-result error'}return}
if(form.id==='store-settings'){e.preventDefault();try{const f=Object.fromEntries(new FormData(form));await api('/api/admin/settings',{method:'PATCH',body:JSON.stringify({...f,shippingFee:Number(f.shippingFee),freeShippingThreshold:Number(f.freeShippingThreshold)})});await loadCatalog();await saveAdmin()}catch(err){form.querySelector('.form-result').textContent=err.message}return}
if(form.id==='product-create'){e.preventDefault();const f=Object.fromEntries(new FormData(form));try{await api('/api/admin/product',{method:'POST',body:JSON.stringify({...f,price:Number(f.price),colours:f.colours.split(',').map(x=>x.trim()).filter(Boolean),sizes:f.sizes.split(',').map(x=>x.trim()).filter(Boolean)})});await loadCatalog();await saveAdmin()}catch(err){form.querySelector('.form-result').textContent=err.message}return}});
window.addEventListener('hashchange',()=>{store.menuOpen=false;render();window.scrollTo({top:0,behavior:'smooth'})});
(async()=>{try{await Promise.all([loadCatalog(),api('/api/me').then(x=>store.me=x)]);if(store.me.authenticated){const [w,o,c,ad]=await Promise.all([api('/api/wishlist'),api('/api/orders'),api('/api/cart'),api('/api/addresses')]);store.addresses=ad.addresses;const merged=new Map();for(const line of [...c.items,...store.cart]){const p=store.products.find(x=>x.id===line.productId);if(!p)continue;const key=keyLine(line),available=stockFor(p,line.colour,line.size);if(!available)continue;const current=merged.get(key);merged.set(key,{...line,quantity:Math.min(available,Math.max(current?.quantity||0,line.quantity))})}store.cart=[...merged.values()];persist();store.wish=new Set([...store.wish,...w.ids]);localStorage.setItem('rr-wish',JSON.stringify([...store.wish]));for(const id of store.wish)api('/api/wishlist',{method:'PUT',body:JSON.stringify({productId:id,active:true})}).catch(()=>{});store.orders=o.orders;const checkoutId=sessionStorage.getItem('rr-checkout-id');if(checkoutId)pendingOrder=store.orders.find(x=>x.id===checkoutId&&x.paymentStatus==='Awaiting payment verification')||null;}render()}catch(error){app.innerHTML='<main class="page"><div class="empty"><h1 class="page-title">A MOMENT, PLEASE.</h1><p>'+esc(error.message)+'</p><button class="button" onclick="location.reload()">Try again</button></div></main>'}})();

